// Pseudo-code: fit a per-language classifier and a bilingual retriever
const modelEN = trainLR(tfIdf(examplesEN), labelsEN);
const modelES = trainLR(tfIdf(examplesES), labelsES);

function predict(msg){
  const lang = detect(msg);
  const vec = tfIdf(msg, lang);
  const model = lang === 'en' ? modelEN : modelES;
  return model.predict(vec);
}
